/* -----------------------------------------------------------------------
 * test_touch_filter.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29 Oct 2026 for Tony's display/UI subsystem (best-ui).
 * BJT2 Sound Modulating Toy — Touch Press Filter Unit Tests
 * Subsystem: Display/UI (Tony). Generative AI was used to assist.
 *
 * Covers touch_filter.c using the Unity test framework.
 * No hardware required — runs on any host PC via CMake.
 *
 * Samples are written as letters: P = PRESSED, R = RELEASED,
 * U = UNSURE. What the filter did with each one is written the same
 * way: T = tap, H = held, . = nothing.
 *
 * Test groups:
 *   Group A — touch_classify: thresholds, spread, one pair in range
 *   Group B — touch_filter_update: one press is one tap
 *   Group C — HELD only on a PRESSED sample; every 8-sample sequence
 *   Group D — init, NULL and unknown samples
 * ----------------------------------------------------------------------- */

#include "unity.h"
#include <stddef.h>
#include <stdio.h>
#include <string.h>
#include "touch_filter.h"
#include "ui_types.h"

void setUp(void)   {}
void tearDown(void) {}

#define LO      TOUCH_NO_PRESS_THRESHOLD_LOW    /* 100: lowest count of a press  */
#define HI      TOUCH_NO_PRESS_THRESHOLD_HIGH   /* 4000: highest count of a press */
#define MID     2000U                           /* a finger in the middle         */
#define NONE    4095U                           /* untouched: the pull-up's count */

/* Shared output of run() */
static char s_out[64];

/* Helper — the sample a letter stands for */
static touch_sample_t sample_of(char c)
{
    return (c == 'P') ? TOUCH_SAMPLE_PRESSED :
           (c == 'R') ? TOUCH_SAMPLE_RELEASED : TOUCH_SAMPLE_UNSURE;
}

/* Helper — feed seq to a fresh filter, one letter per sample, and return
 * what the filter did with each sample, as letters */
static const char *run(const char *seq)
{
    touch_filter_t f;
    size_t i = 0U;

    touch_filter_init(&f);
    for (; seq[i] != '\0' && i < sizeof(s_out) - 1U; i++) {
        touch_action_t a = touch_filter_update(&f, sample_of(seq[i]));
        s_out[i] = (a == TOUCH_ACT_TAP) ? 'T' : ((a == TOUCH_ACT_HELD) ? 'H' : '.');
    }
    s_out[i] = '\0';
    return s_out;
}

/* Helper — number of taps for seq */
static unsigned taps(const char *seq)
{
    unsigned n = 0U;

    for (const char *r = run(seq); *r != '\0'; r++) {
        if (*r == 'T') {
            n++;
        }
    }
    return n;
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP A — touch_classify
 * ═══════════════════════════════════════════════════════════════════════ */

void test_A01_steady_finger_is_pressed(void)
{
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(MID, MID, MID, MID));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(LO, LO, LO, LO));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(HI, HI, HI, HI));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(LO, HI, LO, HI));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(1000U, 3000U, 1100U, 2900U));
}

void test_A02_no_finger_is_released(void)
{
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_RELEASED, touch_classify(NONE, NONE, NONE, NONE));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_RELEASED, touch_classify(0U, 0U, 0U, 0U));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_RELEASED, touch_classify(LO - 1U, LO - 1U, LO - 1U, LO - 1U));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_RELEASED, touch_classify(HI + 1U, HI + 1U, HI + 1U, HI + 1U));
    /* A pair counts only with both of its values in range: X in range
     * and Y out, in both pairs, is still no finger. */
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_RELEASED, touch_classify(MID, NONE, MID, NONE));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_RELEASED, touch_classify(NONE, MID, LO - 1U, MID));
}

void test_A03_spread_150_is_pressed_151_is_unsure(void)
{
    /* X reads 150 apart, either way round */
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(MID, MID, MID + 150U, MID));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(MID + 150U, MID, MID, MID));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE,  touch_classify(MID, MID, MID + 151U, MID));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE,  touch_classify(MID + 151U, MID, MID, MID));
    /* Y the same */
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(MID, MID, MID, MID + 150U));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(MID, MID + 150U, MID, MID));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE,  touch_classify(MID, MID, MID, MID + 151U));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE,  touch_classify(MID, MID + 151U, MID, MID));
    /* Both axes at the limit together */
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_PRESSED, touch_classify(MID, MID, MID - 150U, MID + 150U));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE,  touch_classify(MID, MID, MID - 150U, MID + 151U));
}

void test_A04_one_pair_in_range_is_unsure(void)
{
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE, touch_classify(MID, MID, NONE, NONE));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE, touch_classify(NONE, NONE, MID, MID));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE, touch_classify(MID, MID, MID, LO - 1U));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE, touch_classify(MID, MID, HI + 1U, MID));
    /* At the edge: the second pair just in range, the first just out */
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE, touch_classify(LO - 1U, LO, LO, LO));
    TEST_ASSERT_EQUAL_INT(TOUCH_SAMPLE_UNSURE, touch_classify(HI, HI + 1U, HI, HI));
}

/* Helper — one count inside the press window */
static bool in_range(uint16_t v)
{
    return v >= LO && v <= HI;
}

/* Helper — |a - b| <= TOUCH_SPREAD_MAX */
static bool close_enough(uint16_t a, uint16_t b)
{
    unsigned d = (a > b) ? (unsigned)(a - b) : (unsigned)(b - a);

    return d <= TOUCH_SPREAD_MAX;
}

void test_A05_every_threshold_mix_follows_the_rule(void)
{
    static const uint16_t v[] = { 0U, LO - 1U, LO, LO + 1U, MID, HI - 1U, HI, HI + 1U, NONE };
    const size_t n = sizeof(v) / sizeof(v[0]);
    char msg[48];

    for (size_t a = 0U; a < n; a++) {
        for (size_t b = 0U; b < n; b++) {
            for (size_t c = 0U; c < n; c++) {
                for (size_t d = 0U; d < n; d++) {
                    bool first  = in_range(v[a]) && in_range(v[b]);     /* (x1, y1) */
                    bool second = in_range(v[c]) && in_range(v[d]);     /* (x2, y2) */
                    touch_sample_t want = TOUCH_SAMPLE_UNSURE;

                    if (!first && !second) {
                        want = TOUCH_SAMPLE_RELEASED;
                    } else if (first && second && close_enough(v[a], v[c]) && close_enough(v[b], v[d])) {
                        want = TOUCH_SAMPLE_PRESSED;
                    }
                    snprintf(msg, sizeof(msg), "x1 %u y1 %u x2 %u y2 %u",
                             (unsigned)v[a], (unsigned)v[b], (unsigned)v[c], (unsigned)v[d]);
                    TEST_ASSERT_EQUAL_INT_MESSAGE(want, touch_classify(v[a], v[b], v[c], v[d]), msg);
                }
            }
        }
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP B — touch_filter_update: one press is one tap
 * ═══════════════════════════════════════════════════════════════════════ */

void test_B01_one_pressed_sample_is_one_tap(void)
{
    TEST_ASSERT_EQUAL_STRING("T", run("P"));
    TEST_ASSERT_EQUAL_UINT(1U, taps("P"));
}

void test_B02_a_long_press_is_one_tap_then_held(void)
{
    char seq[51];
    char want[51];

    memset(seq, 'P', 50U);
    seq[50] = '\0';
    memset(want, 'H', 50U);
    want[0]  = 'T';
    want[50] = '\0';
    TEST_ASSERT_EQUAL_STRING(want, run(seq));
    TEST_ASSERT_EQUAL_UINT(1U, taps(seq));
}

void test_B03_an_unsure_sample_does_not_end_the_press(void)
{
    TEST_ASSERT_EQUAL_STRING("T.H", run("PUP"));
    TEST_ASSERT_EQUAL_UINT(1U, taps("PUP"));
    TEST_ASSERT_EQUAL_STRING("T....H", run("PUUUUP"));
}

void test_B04_one_released_sample_does_not_end_the_press(void)
{
    TEST_ASSERT_EQUAL_STRING("T.H", run("PRP"));
    TEST_ASSERT_EQUAL_UINT(1U, taps("PRP"));
}

void test_B05_two_released_samples_end_the_press(void)
{
    TEST_ASSERT_EQUAL_STRING("T..T", run("PRRP"));
    TEST_ASSERT_EQUAL_UINT(2U, taps("PRRP"));
    TEST_ASSERT_EQUAL_STRING("T....T", run("PRRRRP"));
    TEST_ASSERT_EQUAL_UINT(3U, taps("PPRRPPRRP"));
}

void test_B06_unsure_samples_do_not_reset_the_release_count(void)
{
    /* The second R ends the press even with U samples around it */
    TEST_ASSERT_EQUAL_STRING("T....T", run("PURURP"));
    TEST_ASSERT_EQUAL_UINT(2U, taps("PURURP"));
}

void test_B07_no_pressed_sample_no_tap(void)
{
    TEST_ASSERT_EQUAL_STRING("..........", run("RRRRRRRRRR"));
    TEST_ASSERT_EQUAL_STRING("..........", run("UUUUUUUUUU"));
    TEST_ASSERT_EQUAL_UINT(0U, taps("RURUURRUUR"));
    TEST_ASSERT_EQUAL_UINT(0U, taps(""));
}

void test_B08_unsure_samples_before_a_press_do_not_start_it(void)
{
    TEST_ASSERT_EQUAL_STRING("..THH", run("UUPPP"));
    TEST_ASSERT_EQUAL_STRING("...T", run("UURP"));
}

void test_B09_single_releases_between_pressed_samples_never_end_it(void)
{
    /* A light finger: every other sample out of range */
    TEST_ASSERT_EQUAL_STRING("T.H.H.H.H", run("PRPRPRPRP"));
    TEST_ASSERT_EQUAL_UINT(1U, taps("PRPRPRPRP"));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP C — HELD only on a PRESSED sample; every 8-sample sequence
 * ═══════════════════════════════════════════════════════════════════════ */

void test_C01_held_comes_only_on_a_pressed_sample(void)
{
    const char *seq = "PUPRPUUPRRUP";
    const char *got = run(seq);

    TEST_ASSERT_EQUAL_STRING("T.H.H..H...T", got);
    for (size_t i = 0U; seq[i] != '\0'; i++) {
        if (got[i] == 'H' || got[i] == 'T') {
            TEST_ASSERT_EQUAL_CHAR('P', seq[i]);
        }
    }
}

void test_C02_every_8_sample_sequence_follows_the_rule(void)
{
    static const char letters[3] = { 'P', 'R', 'U' };
    char     seq[9];
    char     want[9];
    unsigned long total = 1UL;

    for (int i = 0; i < 8; i++) {
        total *= 3UL;                                   /* 3^8 = 6561 */
    }
    for (unsigned long code = 0UL; code < total; code++) {
        unsigned long c = code;
        bool     seen_p = false;
        unsigned rel = 0U;                              /* R since the last P */

        for (int i = 0; i < 8; i++) {
            seq[i] = letters[c % 3UL];
            c /= 3UL;
        }
        seq[8] = '\0';
        /* The rule from the header: a P is a tap when no P came before
         * it, or when TOUCH_RELEASE_SAMPLES R came since the last one;
         * every other P is held; R and U do nothing. */
        for (int i = 0; i < 8; i++) {
            if (seq[i] == 'P') {
                want[i] = (!seen_p || rel >= TOUCH_RELEASE_SAMPLES) ? 'T' : 'H';
                seen_p = true;
                rel = 0U;
            } else {
                want[i] = '.';
                if (seq[i] == 'R') {
                    rel++;
                }
            }
        }
        want[8] = '\0';
        TEST_ASSERT_EQUAL_STRING_MESSAGE(want, run(seq), seq);
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP D — init, NULL and unknown samples
 * ═══════════════════════════════════════════════════════════════════════ */

void test_D01_init_means_no_finger_down(void)
{
    static touch_filter_t zeroed;                   /* a static starts at 0 */
    touch_filter_t f;

    touch_filter_init(&f);
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_TAP, touch_filter_update(&f, TOUCH_SAMPLE_PRESSED));
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(&f, TOUCH_SAMPLE_RELEASED));
    touch_filter_init(&f);                          /* down, one release: reset */
    TEST_ASSERT_EQUAL_UINT8(0U, f.down);
    TEST_ASSERT_EQUAL_UINT8(0U, f.released);
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_TAP, touch_filter_update(&f, TOUCH_SAMPLE_PRESSED));
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_TAP, touch_filter_update(&zeroed, TOUCH_SAMPLE_PRESSED));
}

void test_D02_null_is_safe(void)
{
    touch_filter_init(NULL);
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(NULL, TOUCH_SAMPLE_PRESSED));
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(NULL, TOUCH_SAMPLE_RELEASED));
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(NULL, TOUCH_SAMPLE_UNSURE));
}

void test_D03_an_unknown_sample_changes_nothing(void)
{
    const touch_sample_t bad = (touch_sample_t)7;
    touch_filter_t f;

    touch_filter_init(&f);                          /* up: no tap, still up */
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(&f, bad));
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_TAP, touch_filter_update(&f, TOUCH_SAMPLE_PRESSED));
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(&f, TOUCH_SAMPLE_RELEASED));
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(&f, bad));   /* down, 1 release */
    TEST_ASSERT_EQUAL_UINT8(1U, f.down);
    TEST_ASSERT_EQUAL_UINT8(1U, f.released);
    TEST_ASSERT_EQUAL_INT(TOUCH_ACT_NONE, touch_filter_update(&f, TOUCH_SAMPLE_RELEASED));
    TEST_ASSERT_EQUAL_UINT8(0U, f.down);            /* the second release ended it */
}

/* ═══════════════════════════════════════════════════════════════════════
 * TEST RUNNER
 * ═══════════════════════════════════════════════════════════════════════ */

int main(void)
{
    UNITY_BEGIN();

    /* Group A — touch_classify */
    RUN_TEST(test_A01_steady_finger_is_pressed);
    RUN_TEST(test_A02_no_finger_is_released);
    RUN_TEST(test_A03_spread_150_is_pressed_151_is_unsure);
    RUN_TEST(test_A04_one_pair_in_range_is_unsure);
    RUN_TEST(test_A05_every_threshold_mix_follows_the_rule);

    /* Group B — one press is one tap */
    RUN_TEST(test_B01_one_pressed_sample_is_one_tap);
    RUN_TEST(test_B02_a_long_press_is_one_tap_then_held);
    RUN_TEST(test_B03_an_unsure_sample_does_not_end_the_press);
    RUN_TEST(test_B04_one_released_sample_does_not_end_the_press);
    RUN_TEST(test_B05_two_released_samples_end_the_press);
    RUN_TEST(test_B06_unsure_samples_do_not_reset_the_release_count);
    RUN_TEST(test_B07_no_pressed_sample_no_tap);
    RUN_TEST(test_B08_unsure_samples_before_a_press_do_not_start_it);
    RUN_TEST(test_B09_single_releases_between_pressed_samples_never_end_it);

    /* Group C — HELD only on P; every 8-sample sequence */
    RUN_TEST(test_C01_held_comes_only_on_a_pressed_sample);
    RUN_TEST(test_C02_every_8_sample_sequence_follows_the_rule);

    /* Group D — init, NULL and unknown samples */
    RUN_TEST(test_D01_init_means_no_finger_down);
    RUN_TEST(test_D02_null_is_safe);
    RUN_TEST(test_D03_an_unknown_sample_changes_nothing);

    return UNITY_END();
}
